# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">YATAY, EĞİMLİ VE DÜŞEY SİLİNDİRİK VİRAJ MODELLERİ</text>\n  <rect x="18" y="44" width="212" height="184" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="124" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. YATAY VİRAJ</text>\n  <rect x="30" y="78" width="188" height="136" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="124" y="100" text-anchor="middle" font-size="10" fill="#334155">Merkezcil kuvveti statik</text>\n  <text x="124" y="116" text-anchor="middle" font-size="10" fill="#334155">sürtünme kuvveti sağlar:</text>\n  <text x="124" y="138" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">m·v² / r ≤ k·m·g</text>\n  <rect x="44" y="150" width="160" height="32" rx="5" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="124" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">vmax = kök(k · g · r)</text>\n  <text x="124" y="200" text-anchor="middle" font-size="9.5" fill="#475569">Kütleden (m) bağımsızdır!</text>\n  <rect x="244" y="44" width="212" height="184" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. EĞİMLİ VİRAJ</text>\n  <rect x="256" y="78" width="188" height="136" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="350" y="100" text-anchor="middle" font-size="10" fill="#334155">Normal kuvvetin yatay</text>\n  <text x="350" y="116" text-anchor="middle" font-size="10" fill="#334155">bileşeni merkeze yönelir:</text>\n  <text x="350" y="138" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">N·sin(α) = m·v²/r , N·cos(α) = m·g</text>\n  <rect x="270" y="150" width="160" height="32" rx="5" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">v = kök(g · r · tan(α))</text>\n  <text x="350" y="200" text-anchor="middle" font-size="9.5" fill="#475569">Eğim açısı α arttıkça v artar.</text>\n  <rect x="470" y="44" width="212" height="184" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="576" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. DÜŞEY SİLİNDİR</text>\n  <rect x="482" y="78" width="188" height="136" rx="6" fill="#ffffff" stroke="#fbbf24"/>\n  <text x="576" y="100" text-anchor="middle" font-size="10" fill="#334155">Duvar tepkisi N = m·v²/r</text>\n  <text x="576" y="116" text-anchor="middle" font-size="10" fill="#334155">Düşmemek için Fs ≥ m·g:</text>\n  <text x="576" y="138" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">k · (m·v² / r) ≥ m·g</text>\n  <rect x="496" y="150" width="160" height="32" rx="5" fill="#fffbeb" stroke="#f59e0b"/>\n  <text x="576" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">vmin = kök(g · r / k)</text>\n  <text x="576" y="200" text-anchor="middle" font-size="9.5" fill="#475569">En küçük güvenli sürattir.</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DÜŞEY DÜZLEMDE ÇEMBERSEL HAREKETTE İP GERİLMESİ (T)</text>\n  <circle cx="175" cy="138" r="78" fill="none" stroke="#94a3b8" stroke-width="2" stroke-dasharray="5,4"/>\n  <circle cx="175" cy="138" r="4" fill="#0f172a"/>\n  <line x1="175" y1="138" x2="175" y2="60" stroke="#2563eb" stroke-width="2"/>\n  <line x1="175" y1="138" x2="175" y2="216" stroke="#dc2626" stroke-width="2"/>\n  <line x1="175" y1="138" x2="253" y2="138" stroke="#16a34a" stroke-width="2"/>\n  <circle cx="175" cy="60" r="10" fill="#3b82f6"/>\n  <circle cx="175" cy="216" r="10" fill="#ef4444"/>\n  <circle cx="253" cy="138" r="10" fill="#22c55e"/>\n  <text x="175" y="44" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">ÜST (K): Tmin</text>\n  <text x="175" y="238" text-anchor="middle" font-size="10" font-weight="bold" fill="#991b1b">ALT (M): Tmax</text>\n  <text x="292" y="142" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">YAN (L)</text>\n  <rect x="345" y="45" width="335" height="58" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.6"/>\n  <text x="512" y="65" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">1. EN ÜST NOKTA (K — Minimum Gerilme)</text>\n  <text x="512" y="86" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">Tüst = (m · v² / r) - m · g</text>\n  <rect x="345" y="112" width="335" height="58" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.6"/>\n  <text x="512" y="132" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">2. YATAY YAN NOKTA (L — Orta Gerilme)</text>\n  <text x="512" y="153" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">Tyan = m · v² / r   (G diktir)</text>\n  <rect x="345" y="179" width="335" height="58" rx="8" fill="#fee2e2" stroke="#dc2626" stroke-width="1.6"/>\n  <text x="512" y="199" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">3. EN ALT NOKTA (M — Maksimum Gerilme)</text>\n  <text x="512" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">Talt = (m · v² / r) + m · g</text>\n</svg>', '<svg viewBox="0 0 700 225" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="225" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DÜŞEY RAY (LOOP) VE TÜMSEK/ÇUKUR KÖPRÜ TEPKİ KUVVETLERİ</text>\n  <rect x="20" y="45" width="210" height="162" rx="10" fill="#e0e7ff" stroke="#4f46e5" stroke-width="1.8"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#3730a3">1. DÜŞEY RAY TEPE NOKTASI</text>\n  <text x="125" y="92" text-anchor="middle" font-size="10" fill="#334155">Rayın iç yüzeyinde üst nokta:</text>\n  <text x="125" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e1b4b">Nüst = (m · v² / r) - m · g</text>\n  <text x="125" y="140" text-anchor="middle" font-size="9.5" fill="#334155">Raydan düşmeme şartı (N ≥ 0):</text>\n  <text x="125" y="162" text-anchor="middle" font-size="10" font-weight="bold" fill="#4338ca">vmin = kök(g · r)</text>\n  <rect x="245" y="45" width="210" height="162" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">2. DIŞBÜKEY (TÜMSEK) KÖPRÜ</text>\n  <text x="350" y="92" text-anchor="middle" font-size="10" fill="#334155">Merkez aşağıda (G merkeze doğru):</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">N = m · g - (m · v² / r)</text>\n  <text x="350" y="140" text-anchor="middle" font-size="9.5" fill="#334155">Sürat arttıkça tepki azalır;</text>\n  <text x="350" y="162" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">N &lt; m · g (Ağırlıktan küçük)</text>\n  <rect x="470" y="45" width="210" height="162" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">3. İÇBÜKEY (ÇUKUR) KÖPRÜ</text>\n  <text x="575" y="92" text-anchor="middle" font-size="10" fill="#334155">Merkez yukarıda (N merkeze doğru):</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">N = m · g + (m · v² / r)</text>\n  <text x="575" y="140" text-anchor="middle" font-size="9.5" fill="#334155">Sürat arttıkça tepki artar;</text>\n  <text x="575" y="162" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">N &gt; m · g (Ağırlıktan büyük)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
